// Original EntropyLab wallpaper, embedded unchanged for both file:// and built pages.
(() => {
  "use strict";
  const BL = window.BL = window.BL || {};
  let image = null;
  BL.labWallpaper = {
    width: 1241, height: 741,
    src: "data:image/jpeg;base64,",
    load() {
      if (!image) {
        image = new Image();
        image.src = this.src;
      }
      return image;
    }
  };
})();
